-- D38: puzzle themes (for themed achievements like the Ultrarare Inferno Jacket) + the fire_ultralinks metric.
-- A puzzle is fire-themed if either concept is a fire word (tagged automatically on insert/update), or if a
-- curator adds 'fire' to its themes by hand.
alter table public.puzzles add column if not exists themes text[] not null default '{}';

create or replace function public.puzzle_auto_themes() returns trigger
language plpgsql set search_path = public as $$
begin
  if upper(new.concept_a) = any(public.fire_words()) or upper(new.concept_b) = any(public.fire_words()) then
    if not ('fire' = any(new.themes)) then new.themes := new.themes || 'fire'::text; end if;
  end if;
  return new;
end $$;

create or replace function public.fire_words() returns text[]
language sql immutable set search_path = public as $$
  select array['FIRE', 'FLAME', 'FLAMES', 'BLAZE', 'INFERNO', 'VOLCANO', 'LAVA', 'MAGMA', 'DRAGON', 'PHOENIX', 'SUN', 'CANDLE',
               'BONFIRE', 'CAMPFIRE', 'FIREWORK', 'FIREWORKS', 'EMBER', 'EMBERS', 'TORCH', 'FURNACE', 'MATCH', 'MATCHES',
               'FIREPLACE', 'FIREFIGHTER', 'SMOKE', 'HEAT', 'SPICE', 'CHILI', 'ROCKET']
$$;

drop trigger if exists puzzles_auto_themes on public.puzzles;
create trigger puzzles_auto_themes before insert or update of concept_a, concept_b, themes on public.puzzles
for each row execute function public.puzzle_auto_themes();
update public.puzzles set themes = themes where true;  -- backfill through the trigger

create or replace function public.vault_metrics(p_player uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  today date := public.utc_today();
  dailies int; best int; cur int; perfect int; ultra int; placed int; win_streak int;
  diamond int; sci int; fz int; fire int;
begin
  select count(*), coalesce(sum((pts >= n * 100)::int), 0) into dailies, perfect from public.vault_dailies(p_player);
  -- streaks: islands of consecutive days
  with x as (select d, d - (row_number() over (order by d))::int as grp from public.vault_dailies(p_player)),
       isl as (select min(d) s, max(d) e, count(*) len from x group by grp)
  select coalesce(max(len), 0), coalesce(max(len) filter (where e >= today - 1), 0) into best, cur from isl;
  select count(*) into ultra from public.attempts a join public.accepted_answers aa on aa.id = a.accepted_answer_id
   where a.player_id = p_player and a.mode = 'daily' and aa.tier = 'ULTRALINK';
  select coalesce(max(placements), 0) into placed from public.ranked_ratings where player_id = p_player;
  with r as (select won, finished_at, (row_number() over (order by finished_at) - row_number() over (partition by won order by finished_at)) g
               from public.vault_ranked(p_player))
  select coalesce(max(c), 0) into win_streak from (select count(*) c from r where won group by g) t;
  select count(*) into diamond from (
    select m.season from public.ranked_players rp join public.ranked_matches m on m.id = rp.match_id
     where rp.player_id = p_player and rp.rp_after >= 1500
     group by m.season having count(distinct m.queue) = 2) t;
  select count(distinct season) into sci from public.ranked_honours where player_id = p_player and honour = 'scientist';
  select count(*) into fz from public.frenzy_results where p_player = any(winners) and players >= public.vault_cfg('frenzy_min_players');
  -- distinct ULTRALINK answers found in fire-themed puzzles (daily, Unlimited, ranked); repeats don't count
  select count(*) into fire from (
    select a.puzzle_id, a.accepted_answer_id from public.attempts a
      join public.accepted_answers aa on aa.id = a.accepted_answer_id join public.puzzles p on p.id = a.puzzle_id
     where a.player_id = p_player and a.mode in ('daily', 'unlimited') and aa.tier = 'ULTRALINK' and 'fire' = any(p.themes)
    union
    select rd.puzzle_id, s.accepted_answer_id from public.ranked_subs s
      join public.ranked_rounds rd on rd.match_id = s.match_id and rd.round_no = s.round_no
      join public.accepted_answers aa on aa.id = s.accepted_answer_id join public.puzzles p on p.id = rd.puzzle_id
     where s.player_id = p_player and aa.tier = 'ULTRALINK' and 'fire' = any(p.themes)) f;
  return jsonb_build_object('fire_ultralinks', fire, 'dailies', dailies, 'streak', cur, 'best_streak', best, 'perfect', perfect, 'ultralinks', ultra,
    'placements', placed, 'win_streak', win_streak, 'diamond_both', diamond, 'scientist_seasons', sci,
    'frenzy_wins', fz);
end $$;

revoke execute on function public.vault_metrics(uuid), public.fire_words() from public, anon, authenticated;
-- Generated by scripts/vault-catalog.py. Do not edit by hand.
select public.ranked_season();  -- makes sure the current ranked season exists
on conflict (code) do update set starts_at = excluded.starts_at, ends_at = excluded.ends_at;
on conflict (code) do update set name = excluded.name, starts_at = excluded.starts_at, ends_at = excluded.ends_at;

on conflict (code) do update set name = excluded.name, description = excluded.description, metric = excluded.metric, target = excluded.target,
  event = excluded.event, reward_volts = excluded.reward_volts, reward_items = excluded.reward_items, sort = excluded.sort;

on conflict (slug) do update set name = excluded.name, slot = excluded.slot, tier = excluded.tier, description = excluded.description,
  unlock = excluded.unlock, price = excluded.price, achievement = excluded.achievement, event = excluded.event, contents = excluded.contents,
  sort = excluded.sort, active = true;

-- Items no longer in the catalogue stay in the table (owners keep them) but are hidden from the Vault.
update public.cosmetic_items set active = false where slug not in ('base-classic-spark', 'fil-classic', 'bulb-red', 'bulb-gold', 'bulb-blue', 'bulb-green', 'hat-cap', 'hat-beanie', 'head-bucket', 'hat-sprout', 'out-navy-hoodie', 'out-tee', 'out-grey-tee', 'out-stripe-tee', 'ban-classic', 'ban-sky', 'ban-sunset', 'ban-mint', 'bulb-pink', 'bulb-orange', 'bulb-violet', 'bulb-cyan', 'base-grin', 'base-dreamer', 'fil-spiral', 'fil-heart', 'out-blue-hoodie', 'out-puffer', 'hat-party', 'hat-headphones', 'head-propeller', 'eyes-round', 'eyes-shades', 'acc-coffee', 'acc-book', 'fx-glow', 'ban-forest', 'ban-ocean', 'bulb-fade-sunset', 'bulb-fade-ocean', 'bulb-fade-mint', 'hat-tophat', 'hat-wizard', 'eyes-star', 'eyes-visor', 'fil-bolt', 'out-dark-tech', 'out-midnight-hoodie', 'acc-flask', 'fx-sparks', 'ban-grid', 'bulb-fade-twilight', 'bulb-rose-gold', 'fil-infinity', 'out-varsity', 'head-viking', 'hat-halo', 'eyes-watt-specs', 'acc-lightning-rod', 'ban-voltage', 'bulb-molten-gold', 'bulb-neon-pulse', 'fil-golden', 'out-lab-coat', 'head-royal-crown', 'fx-golden-shimmer', 'ban-aurora', 'bulb-s1-aurora', 'head-s1-beanie', 'fx-winter-snow', 'head-santa', 'bulb-candy-cane', 'bulb-frost', 'out-xmas-sweater', 'base-neon', 'base-circuit', 'base-overload', 'base-professor-watt', 'bundle-neon', 'bundle-circuit', 'bundle-overload', 'bundle-professor', 'ban-first-light', 'acc-torch', 'eyes-starlight', 'out-perfect-circuit', 'fil-ultralink', 'bulb-eternal-flame', 'ban-ranked', 'head-frenzy-crown', 'fx-unbreakable', 'out-inferno-jacket', 'fx-rainbow-lightning', 'base-scientist', 'ban-scientist', 'ban-s1', 'out-s1-founder', 'ban-winter', 'acc-candy-cane', 'fx-scientist-legacy', 'base-first-spark');
